create virtual table if not exists "content_fts" using fts5(
      "body", content='content', content_rowid='entity'
    )

create trigger if not exists "content_fts_insert" after insert on "content" begin
      insert into "content_fts"(rowid, "body") values (new.entity, coalesce(new."body", ''));
    end

create trigger if not exists "content_fts_update" after update on "content" begin
      insert into "content_fts"("content_fts", rowid, "body")
        values ('delete', old.entity, coalesce(old."body", ''));
      insert into "content_fts"(rowid, "body") values (new.entity, coalesce(new."body", ''));
    end

create virtual table if not exists "doc_fts" using fts5(
      "title", "body", content='doc_text', content_rowid='entity'
    )

create trigger if not exists "doc_fts_insert" after insert on "doc" begin
      insert into "doc_fts"(rowid, "title", "body") values (new.entity, coalesce(new."title", ''), coalesce((select value from blob_text where entity = new."body"), ''));
    end

create trigger if not exists "doc_fts_update" after update on "doc" begin
      insert into "doc_fts"("doc_fts", rowid, "title", "body")
        values ('delete', old.entity, coalesce(old."title", ''), coalesce((select value from blob_text where entity = old."body"), ''));
      insert into "doc_fts"(rowid, "title", "body") values (new.entity, coalesce(new."title", ''), coalesce((select value from blob_text where entity = new."body"), ''));
    end

